        for x in range(N):
            for y in range(N):
                for nx, ny in get_neighbors(x, y):
                    dp[nx][ny][l] = min(dp[nx][ny][l], dp[x][y][l - 1] + grid[nx][ny])

    min_path = min(dp[N - 1][N - 1])
    return [val for val in dp[N - 1][N - 1] if val == min_path]
